/**
 * Header 4 — interactive 3D grid hero. A perspective grid whose cells light up
 * in the brand colors as the pointer moves across them.
 */

import { ExternalLink } from "lucide-react";
import { useEffect, useRef } from "react";
import { AnimatedGroup } from "../shared/animated-group";
import { AnimatedText } from "../shared/animated-text";
import PressButton from "@/components/elements/press-button";
import { HeroHeader } from "../shared/hero-header";
import styles from "./hero-grid.module.css";

interface InteractiveGridProps {
  hoverColors?: string | [string, string, string, string];
}

const TOTAL_TILES = 1600;
const INITIAL_TILE = 1;
const TILES_TO_CLONE = TOTAL_TILES - INITIAL_TILE;

function InteractiveGrid({ hoverColors }: InteractiveGridProps) {
  const containerRef = useRef<HTMLDivElement>(null);
  const tileRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!(containerRef.current && tileRef.current)) {
      return;
    }

    // Clone the first tile to create a 40x40 grid (1600 tiles total)
    for (let i = 0; i < TILES_TO_CLONE; i++) {
      const clonedTile = tileRef.current.cloneNode(true);
      containerRef.current.appendChild(clonedTile);
    }
  }, []);

  // Prepare CSS variables for hover colors
  const style = hoverColors
    ? {
        "--hero-grid-hover-color-1": Array.isArray(hoverColors)
          ? hoverColors[0]
          : hoverColors,
        "--hero-grid-hover-color-2": Array.isArray(hoverColors)
          ? (hoverColors[1] ?? hoverColors[0])
          : hoverColors,
        "--hero-grid-hover-color-3": Array.isArray(hoverColors)
          ? (hoverColors[2] ?? hoverColors[0])
          : hoverColors,
        "--hero-grid-hover-color-4": Array.isArray(hoverColors)
          ? (hoverColors[3] ?? hoverColors[0])
          : hoverColors,
      }
    : undefined;

  return (
    <div
      aria-hidden="true"
      className={styles.gridContainer}
      style={style as React.CSSProperties}
    >
      <div className={styles.mainGrid} ref={containerRef}>
        <div className={styles.tile} ref={tileRef} />
      </div>
    </div>
  );
}

interface HeroGridProps {
  hoverColors?: string | [string, string, string, string];
}

export function HeroGrid({ hoverColors }: HeroGridProps) {
  return (
    <div className="relative">
      <HeroHeader />
      <main>
        <section className="relative overflow-hidden py-36">
          {/* Interactive animated grid background */}
          <InteractiveGrid hoverColors={hoverColors} />
          <AnimatedGroup
            className="pointer-events-none flex flex-col items-center gap-6 text-center"
            preset="blur-slide"
          >
            <div>
              <AnimatedText
                as="h1"
                className="mb-6 text-pretty font-bold text-2xl tracking-tight lg:text-5xl"
              >
                Build your next project with{" "}
                <span className="text-brand">DX UI</span>
              </AnimatedText>
              <AnimatedText
                as="p"
                className="mx-auto max-w-3xl text-muted-foreground lg:text-xl"
                delay={0.15}
              >
                DX UI gives you the building blocks to create stunning,
                animated interfaces in minutes.
              </AnimatedText>
            </div>
            <AnimatedGroup
              className="pointer-events-auto mt-6 flex justify-center gap-3"
              preset="slide"
            >
              <PressButton
                className="shadow-sm transition-shadow hover:shadow"
                variant="outline"
              >
                Get Started
              </PressButton>
              <PressButton className="group" variant="candy">
                Learn more{" "}
                <ExternalLink className="ml-2 h-4 transition-transform group-hover:translate-x-0.5" />
              </PressButton>
            </AnimatedGroup>
          </AnimatedGroup>
        </section>
      </main>
    </div>
  );
}

export default HeroGrid;

/* Interactive 3D grid: perspective grid with customizable hover colors. */

.gridContainer {
  --hero-grid-hover-color-1: var(--color-brand);
  --hero-grid-hover-color-2: var(--color-brand);
  --hero-grid-hover-color-3: var(--color-brand);
  --hero-grid-hover-color-4: var(--color-brand);
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  perspective: 2000px;
  perspective-origin: center center;
}

.mainGrid {
  position: absolute;
  top: 50%;
  left: 50%;
  display: grid;
  grid-template-rows: repeat(40, 1fr);
  grid-template-columns: repeat(40, 1fr);
  width: 140rem;
  aspect-ratio: 1;
  transform: translate(-50%, -50%) rotateX(50deg) rotateY(-5deg) rotateZ(20deg)
    scale(1.25);
}

.mainGrid::after {
  position: absolute;
  inset: 0;
  z-index: 3;
  pointer-events: none;
  content: "";
  background: radial-gradient(circle, transparent 25%, rgb(255 255 255) 80%);
}

:global(.dark).mainGrid::after {
  background: radial-gradient(
    circle,
    transparent 25%,
    rgb(0 0 0 / 90%) 80%
  ) !important;
}

.tile {
  border: 0.5px solid rgb(0 0 0 / 12%);
  transition: background-color 1500ms;
}

:global(.dark).tile {
  border: 0.5px solid rgb(255 255 255 / 5%);
}

.tile:hover {
  transition-duration: 0ms;
}

.tile:nth-child(4n):hover {
  background-color: var(--hero-grid-hover-color-1);
}

.tile:nth-child(4n + 1):hover {
  background-color: var(--hero-grid-hover-color-2);
}

.tile:nth-child(4n + 2):hover {
  background-color: var(--hero-grid-hover-color-3);
}

.tile:nth-child(4n + 3):hover {
  background-color: var(--hero-grid-hover-color-4);
}

.tile:nth-child(7n):hover {
  background-color: var(--hero-grid-hover-color-2);
}

.tile:nth-child(7n + 3):hover {
  background-color: var(--hero-grid-hover-color-3);
}

.tile:nth-child(7n + 5):hover {
  background-color: var(--hero-grid-hover-color-4);
}

.tile:nth-child(7n + 6):hover {
  background-color: var(--hero-grid-hover-color-1);
}

.tile:nth-child(11n + 1):hover {
  background-color: var(--hero-grid-hover-color-1);
}

.tile:nth-child(11n + 4):hover {
  background-color: var(--hero-grid-hover-color-2);
}

.tile:nth-child(11n + 7):hover {
  background-color: var(--hero-grid-hover-color-3);
}

.tile:nth-child(11n + 10):hover {
  background-color: var(--hero-grid-hover-color-4);
}

@media (prefers-reduced-motion: reduce) {
  .mainGrid {
    transform: translate(-50%, -50%) rotateZ(20deg);
  }

  .tile {
    transition: none;
  }
}

/* Reduce overlay size of hero text/button containers */
.heroContent {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  max-width: 600px;
  padding: 0;
  margin: 0 auto;
  background: none;
  box-shadow: none;
}

.heroButtons {
  display: flex;
  gap: 1rem;
  width: auto;
  padding: 0;
  margin-top: 1.5rem;
  background: none;
  box-shadow: none;
}

import { motion, useReducedMotion, type Variants } from "motion/react";
import React, { type ReactNode } from "react";

export type PresetType =
  | "fade"
  | "slide"
  | "scale"
  | "blur"
  | "blur-slide"
  | "zoom"
  | "flip"
  | "bounce"
  | "rotate"
  | "swing";

export interface AnimatedGroupProps {
  as?: React.ElementType;
  asChild?: React.ElementType;
  children: ReactNode;
  className?: string;
  preset?: PresetType;
  variants?: {
    container?: Variants;
    item?: Variants;
  };
}

const defaultContainerVariants: Variants = {
  visible: {
    transition: {
      staggerChildren: 0.1,
    },
  },
};

const defaultItemVariants: Variants = {
  hidden: { opacity: 0 },
  visible: { opacity: 1 },
};

const presetVariants: Record<PresetType, Variants> = {
  blur: {
    hidden: { filter: "blur(4px)" },
    visible: { filter: "blur(0px)" },
  },
  "blur-slide": {
    hidden: { filter: "blur(4px)", y: 20 },
    visible: { filter: "blur(0px)", y: 0 },
  },
  bounce: {
    hidden: { y: -50 },
    visible: {
      transition: { damping: 10, stiffness: 400, type: "spring" as const },
      y: 0,
    },
  },
  fade: {},
  flip: {
    hidden: { rotateX: -90 },
    visible: {
      rotateX: 0,
      transition: { damping: 20, stiffness: 300, type: "spring" as const },
    },
  },
  rotate: {
    hidden: { rotate: -180 },
    visible: {
      rotate: 0,
      transition: { damping: 15, stiffness: 200, type: "spring" as const },
    },
  },
  scale: {
    hidden: { scale: 0.8 },
    visible: { scale: 1 },
  },
  slide: {
    hidden: { y: 20 },
    visible: { y: 0 },
  },
  swing: {
    hidden: { rotate: -10 },
    visible: {
      rotate: 0,
      transition: { damping: 8, stiffness: 300, type: "spring" as const },
    },
  },
  zoom: {
    hidden: { scale: 0.5 },
    visible: {
      scale: 1,
      transition: { damping: 20, stiffness: 300, type: "spring" as const },
    },
  },
};

const reducedContainerVariants: Variants = {
  hidden: { opacity: 1 },
  visible: { opacity: 1, transition: { staggerChildren: 0 } },
};

const reducedItemVariants: Variants = {
  hidden: { opacity: 1 },
  visible: { opacity: 1 },
};

const addDefaultVariants = (variants: Variants) => ({
  hidden: { ...defaultItemVariants.hidden, ...variants.hidden },
  visible: { ...defaultItemVariants.visible, ...variants.visible },
});

function AnimatedGroup({
  children,
  className,
  variants,
  preset,
  as = "div",
  asChild = "div",
}: AnimatedGroupProps) {
  const shouldReduceMotion = useReducedMotion();

  const selectedVariants = {
    container: addDefaultVariants(defaultContainerVariants),
    item: addDefaultVariants(preset ? presetVariants[preset] : {}),
  };
  const containerVariants = shouldReduceMotion
    ? reducedContainerVariants
    : (variants?.container ?? selectedVariants.container);
  const itemVariants = shouldReduceMotion
    ? reducedItemVariants
    : (variants?.item ?? selectedVariants.item);

  const MotionComponent = motion(as);

  const MotionChild = motion(asChild);

  return (
    <MotionComponent
      animate="visible"
      className={className}
      initial="hidden"
      variants={containerVariants}
    >
      {React.Children.map(children, (child, index) => (
        <MotionChild
          // oxlint-disable-next-line react/no-array-index-key
          key={index}
          variants={itemVariants}
        >
          {child}
        </MotionChild>
      ))}
    </MotionComponent>
  );
}

export { AnimatedGroup };

import { motion, useReducedMotion } from "motion/react";
import type { ElementType, ReactNode } from "react";

interface AnimatedTextProps {
  as?: ElementType;
  children: ReactNode;
  className?: string;
  delay?: number;
}

export function AnimatedText({
  as: Tag = "span",
  children,
  className,
  delay = 0,
}: AnimatedTextProps) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.div
      animate={
        shouldReduceMotion
          ? { opacity: 1 }
          : { filter: "blur(0px)", opacity: 1, y: 0 }
      }
      initial={
        shouldReduceMotion
          ? { opacity: 1 }
          : { filter: "blur(12px)", opacity: 0, y: 12 }
      }
      transition={
        shouldReduceMotion
          ? { duration: 0 }
          : {
              bounce: 0.3,
              delay,
              duration: 1.5,
              type: "spring" as const,
            }
      }
    >
      <Tag className={className}>{children}</Tag>
    </motion.div>
  );
}

import PressButton from "@/components/elements/press-button";
import { Menu, X } from "lucide-react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useState } from "react";

const menuItems = [
  { href: "#features", id: "features", name: "Features" },
  { href: "#pricing", id: "pricing", name: "Pricing" },
  { href: "#about", id: "about", name: "About" },
];

// Animation constants
const ANIMATION_DURATION = 0.2;
const STAGGER_DELAY = 0.05;
const EASE_OUT_QUART_X1 = 0.22;
const EASE_OUT_QUART_Y1 = 1;
const EASE_OUT_QUART_X2 = 0.36;
const EASE_OUT_QUART_Y2 = 1;
const EASE_OUT_QUART = [
  EASE_OUT_QUART_X1,
  EASE_OUT_QUART_Y1,
  EASE_OUT_QUART_X2,
  EASE_OUT_QUART_Y2,
] as const;
const ROTATION_ANGLE = 180;
const SCALE_MIN = 0;
const SCALE_MAX = 1;
const TRANSLATE_Y_OFFSET = -10;
const TRANSLATE_X_OFFSET = -10;

export const HeroHeader = () => {
  const shouldReduceMotion = useReducedMotion();
  const [menuState, setMenuState] = useState(false);

  return (
    <div className="relative">
      <header>
        <nav className="absolute top-0 left-0 z-20 w-full transition-all duration-300">
          <div className="mx-auto max-w-5xl px-6">
            <div className="relative flex flex-wrap items-center justify-between gap-6 py-6 transition-all duration-200 lg:gap-0">
              <div className="flex w-full justify-between gap-6 lg:w-auto">
                <a aria-label="DX UI home" className="flex items-center gap-2" href="/">
                  <img
                    alt=""
                    aria-hidden="true"
                    className="size-6"
                    draggable={false}
                    height={24}
                    src="/brand/dx-mark-128.webp"
                    width={24}
                  />
                  <span className="font-medium text-[15px] tracking-[-0.02em]">
                    DX <span className="text-muted-foreground">UI</span>
                  </span>
                </a>

                <button
                  aria-label={menuState === true ? "Close Menu" : "Open Menu"}
                  className="relative z-20 -m-2.5 -mr-4 block cursor-pointer p-2.5 lg:hidden"
                  onClick={() => setMenuState(!menuState)}
                  type="button"
                >
                  <AnimatePresence mode="wait">
                    {menuState ? (
                      <motion.div
                        animate={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : { opacity: 1, rotate: 0, scale: SCALE_MAX }
                        }
                        exit={
                          shouldReduceMotion
                            ? { opacity: 0, transition: { duration: 0 } }
                            : {
                                opacity: 0,
                                rotate: -ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        initial={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : {
                                opacity: 0,
                                rotate: ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        key="close"
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : {
                                duration: ANIMATION_DURATION,
                                ease: EASE_OUT_QUART,
                              }
                        }
                      >
                        <X className="m-auto size-6" />
                      </motion.div>
                    ) : (
                      <motion.div
                        animate={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : { opacity: 1, rotate: 0, scale: SCALE_MAX }
                        }
                        exit={
                          shouldReduceMotion
                            ? { opacity: 0, transition: { duration: 0 } }
                            : {
                                opacity: 0,
                                rotate: ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        initial={
                          shouldReduceMotion
                            ? { opacity: 1 }
                            : {
                                opacity: 0,
                                rotate: -ROTATION_ANGLE,
                                scale: SCALE_MIN,
                              }
                        }
                        key="menu"
                        transition={
                          shouldReduceMotion
                            ? { duration: 0 }
                            : {
                                duration: ANIMATION_DURATION,
                                ease: EASE_OUT_QUART,
                              }
                        }
                      >
                        <Menu className="m-auto size-6" />
                      </motion.div>
                    )}
                  </AnimatePresence>
                </button>

                <div className="m-auto hidden size-fit lg:block">
                  <ul className="flex gap-1">
                    {menuItems.map((item) => (
                      <li key={item.id}>
                        <PressButton asChild size="sm" variant="ghost">
                          <a className="text-base" href={item.href}>
                            <span>{item.name}</span>
                          </a>
                        </PressButton>
                      </li>
                    ))}
                  </ul>
                </div>
              </div>

              <AnimatePresence>
                {menuState ? (
                  <motion.div
                    animate={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { opacity: 1, scale: SCALE_MAX, y: 0 }
                    }
                    className="mb-6 w-full flex-wrap items-center justify-end space-y-8 rounded-3xl border bg-background p-6 shadow-2xl shadow-zinc-300/20 md:flex-nowrap lg:m-0 lg:flex lg:w-fit lg:gap-6 lg:space-y-0 lg:border-transparent lg:bg-transparent lg:p-0 lg:shadow-none dark:shadow-none dark:lg:bg-transparent"
                    exit={
                      shouldReduceMotion
                        ? { opacity: 0, transition: { duration: 0 } }
                        : { opacity: 0, scale: 0.95, y: TRANSLATE_Y_OFFSET }
                    }
                    initial={
                      shouldReduceMotion
                        ? { opacity: 1 }
                        : { opacity: 0, scale: 0.95, y: TRANSLATE_Y_OFFSET }
                    }
                    transition={
                      shouldReduceMotion
                        ? { duration: 0 }
                        : {
                            duration: ANIMATION_DURATION,
                            ease: EASE_OUT_QUART,
                          }
                    }
                  >
                    <div className="lg:hidden">
                      <ul className="space-y-6 text-base">
                        {menuItems.map((item, index) => (
                          <motion.li
                            animate={
                              shouldReduceMotion
                                ? { opacity: 1 }
                                : { opacity: 1, x: 0 }
                            }
                            initial={
                              shouldReduceMotion
                                ? { opacity: 1 }
                                : { opacity: 0, x: TRANSLATE_X_OFFSET }
                            }
                            key={item.id}
                            transition={
                              shouldReduceMotion
                                ? { duration: 0 }
                                : {
                                    delay: index * STAGGER_DELAY,
                                    duration: ANIMATION_DURATION,
                                    ease: EASE_OUT_QUART,
                                  }
                            }
                          >
                            <a
                              className="block text-muted-foreground duration-150 hover:text-accent-foreground"
                              href={item.href}
                              onClick={() => setMenuState(false)}
                            >
                              <span>{item.name}</span>
                            </a>
                          </motion.li>
                        ))}
                      </ul>
                    </div>
                    <motion.div
                      animate={
                        shouldReduceMotion
                          ? { opacity: 1 }
                          : { opacity: 1, y: 0 }
                      }
                      className="flex w-full flex-col space-y-3 sm:flex-row sm:gap-3 sm:space-y-0 md:w-fit"
                      initial={
                        shouldReduceMotion
                          ? { opacity: 1 }
                          : { opacity: 0, y: 10 }
                      }
                      transition={
                        shouldReduceMotion
                          ? { duration: 0 }
                          : {
                              delay:
                                menuItems.length * STAGGER_DELAY +
                                STAGGER_DELAY,
                              duration: ANIMATION_DURATION,
                              ease: EASE_OUT_QUART,
                            }
                      }
                    >
                      <PressButton
                        onClick={() => setMenuState(false)}
                        size="sm"
                        type="button"
                        variant="ghost"
                      >
                        <span>Login</span>
                      </PressButton>
                      <PressButton
                        onClick={() => setMenuState(false)}
                        size="sm"
                        type="button"
                      >
                        <span>Sign Up</span>
                      </PressButton>
                    </motion.div>
                  </motion.div>
                ) : null}
              </AnimatePresence>
            </div>
          </div>
        </nav>
      </header>
    </div>
  );
};
